import html
import re
import sys
from pathlib import Path

SUBTAG_WIDTH = 3

HEADER = """\
// Generated by scripts/tools/gen/language-tags.py – do not edit.
//
// BCP-47 primary subtag -> OpenType language system tag, for every language the OpenType registry
// names. Derived from the OpenType language system registry, the ISO 639-3 code table and the IANA
// language subtag registry; see the generator for why all three are needed.
//
// **Primary subtags only.** A tag like `zh-Hant` is resolved by `normalize_chinese` in `ot/tag.rs`
// before this table is consulted, because the script and region subtags disagree with each other in
// ways a flat table cannot express.
//
// Fixed-width rather than `&str`, which costs two relocations an entry and makes the table a
// pointer table rather than data.

// How many bytes a primary subtag occupies below. Every registered subtag this table names fits.
pub(crate) const SUBTAG_WIDTH: usize = {width};

// `(primary subtag, OpenType tag)`, sorted by subtag so a lookup can bisect.
//
// A subtag shorter than the array is padded with zero bytes, which sort below every letter and so
// leave the ordering the same as the strings'.
pub(crate) static LANGUAGE_TAGS: &[([u8; SUBTAG_WIDTH], [u8; 4]); {count}] = &[
"""

def parse_opentype(path):
    text = path.read_text(encoding="utf-8", errors="replace")
    out = []
    for row in re.findall(r"<tr>(.*?)</tr>", text, re.S):
        cells = [
            html.unescape(re.sub("<[^>]+>", "", c)).strip()
            for c in re.findall(r"<td.*?>(.*?)</td>", row, re.S)
        ]
        if len(cells) < 3:
            continue
        tag = cells[1].strip().strip("'‘’")
        if not re.fullmatch(r"[A-Za-z0-9 ]{4}", tag):
            continue
        codes = re.findall(r"\b[a-z]{3}\b", cells[2])
        if codes:
            out.append((tag, codes))
    return out

def parse_iso639(path):
    part1 = {}
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines()[1:]:
        fields = line.split("\t")
        if len(fields) > 3 and fields[3].strip():
            part1[fields[0].strip()] = fields[3].strip()
    return part1

def parse_iana(path):
    subtags = set()
    for record in path.read_text(encoding="utf-8", errors="replace").split("%%"):
        if "Type: language" not in record:
            continue
        found = re.search(r"^Subtag: ([A-Za-z]+)", record, re.M)
        if found:
            subtags.add(found.group(1).lower())
    return subtags

SOURCES = {
    "languagetags.html":
        "https://learn.microsoft.com/en-us/typography/opentype/spec/languagetags",
    "language-subtag-registry":
        "https://www.iana.org/assignments/language-subtag-registry/language-subtag-registry",
    "iso-639-3.tab":
        "https://iso639-3.sil.org/sites/iso639-3/files/downloads/iso-639-3.tab",
}

def require(root):
    missing = [n for n in SOURCES if not (root / n).exists()]
    if missing:
        raise SystemExit("\n".join(
            [f"missing under {root}:"]
            + [f"    curl --create-dirs -o {root / n} {SOURCES[n]}" for n in missing]))

def main():
    root = Path(sys.argv[1] if len(sys.argv) > 1 else "scripts/.out/langtags")
    require(root)
    opentype = parse_opentype(root / "languagetags.html")
    part1 = parse_iso639(root / "iso-639-3.tab")
    registered = parse_iana(root / "language-subtag-registry")

    ranked = sorted(
        ((tag, codes) for tag, codes in opentype),
        key=lambda entry: len(entry[1]),
    )

    mapping = {}
    for ot_tag, codes in ranked:
        for code in codes:
            subtag = part1.get(code, code)
            if subtag not in registered or len(subtag) > SUBTAG_WIDTH:
                continue
            mapping.setdefault(subtag, ot_tag)

    for subtag, ot_tag in (("mo", "MOL "), ("no", "NOR ")):
        mapping.setdefault(subtag, ot_tag)

    rows = sorted(mapping.items())
    lines = [HEADER.format(width=SUBTAG_WIDTH, count=len(rows))]
    for subtag, ot_tag in rows:
        key = subtag + "\\0" * (SUBTAG_WIDTH - len(subtag))
        lines.append(f'    (*b"{key}", *b"{ot_tag}"),\n')
    lines.append("];\n")

    out = Path("src/daecore/src/daeshaper/generated/language_tags.rs")
    out.write_text("".join(lines), encoding="utf-8")
    print(f"{len(rows)} subtags -> {out}")
    longest = max(len(s) for s in mapping)
    print(f"longest subtag {longest}, array width {SUBTAG_WIDTH}")

if __name__ == "__main__":
    main()
